mapper.insert:
insert into store_member_recharge (
    id, recharge_no, store_id, user_id, openid, app_id, mch_id,
    amount, amount_fen, pay_status, prepay_id, created_by, created_time, deleted
) values (
    #{id}, #{rechargeNo}, #{storeId}, #{userId}, #{openid}, #{appId}, #{mchId},
    #{amount}, #{amountFen}, #{payStatus}, #{prepayId}, #{createdBy}, #{createdTime}, #{deleted}
)

mapper.update:
update store_member_recharge
set pay_status = 2,
    update_time = #{closedTime}
where recharge_no = #{rechargeNo}
  and deleted = 0
  and pay_status = 0

mapper.select:
select * from store_member_recharge
where deleted = 0
  and pay_status = 0
  and created_time < #{expireBefore}
order by created_time asc
limit #{limit}
